questionvariables.text:
scen: rand(3);
pat: [[1,1,2,3,4,5],[1,1,1,2,3,4],[1,1,2,2,3,4]][scen+1];
pool: random_permutation(["Mary Wanjiku","John Otieno","Peter Mwangi","Grace Achieng","Samuel Kipchoge","Faith Njeri","Hassan Abdi","Esther Chebet","David Mutua","Amina Hussein"]);
perm: random_permutation(pat);
nm: makelist(pool[perm[i]],i,1,6);
cpool: random_permutation(["Nairobi","Kisumu","Kiambu","Nakuru","Mombasa","Eldoret"]);
cty: makelist(cpool[1+rand(4)],i,1,6);
id0: 10400+rand(500);
ids: makelist(id0+i,i,1,6);
yb: random_permutation(makelist(1960+k,k,0,43));
gp: random_permutation([1,2,3,4,5,6]);
jrows: [8,12,10][scen+1];
removed: [1,2,2][scen+1];
dupn: [2,3,4][scen+1];
nrows: 6;
key_options: random_permutation([[kid,true,"National ID"],[kname,false,"Name"],[kcounty,false,"County"],[krow,false,"Row position (first row to first row)"]]);
